def is_sum_free(subset):
    s = set(subset)
    for x in subset:
        for y in subset:
            if x + y in s:
                return False
    return True

def check_n_m(n, m):
    # Check if there exists a partition of {1, ..., n} into m sum-free sets
    sets = [set() for _ in range(m)]
    def backtrack(curr):
        if curr > n:
            return True
        for i in range(m):
            # Check if adding curr to sets[i] keeps it sum-free
            # The only new sum-free violation could be x + y = curr where x, y are in sets[i]
            # or curr + x = y where x, y are in sets[i] (impossible as curr is largest)
            # or curr + curr = x where x is in sets[i] (impossible as curr is largest)
            possible = True
            for x in sets[i]:
                if x + x == curr:
                    possible = False
                    break
                for y in sets[i]:
                    if x + y == curr:
                        possible = False
                        break
                if not possible: break

            if possible:
                sets[i].add(curr)
                if backtrack(curr + 1):
                    return True
                sets[i].remove(curr)
        return False
    return backtrack(1)

