def check_n_m(n, m):
    sets = [[] for _ in range(m)]
    def backtrack(curr):
        if curr > n:
            return True
        for i in range(m):
            # Check if curr + x = y where x, y are in sets[i]
            # or x + y = curr where x, y are in sets[i]
            # or curr + curr = x (impossible)
            # or curr + x = curr (impossible)
            # Since curr is the largest, we only check x + y = curr
            # where x and y are in sets[i].
            possible = True
            for idx1 in range(len(sets[i])):
                x = sets[i][idx1]
                # Check x + x = curr
                if x + x == curr:
                    possible = False
                    break
                # Check x + y = curr
                for idx2 in range(idx1 + 1, len(sets[i])):
                    y = sets[i][idx2]
                    if x + y == curr:
                        possible = False
                        break
                if not possible: break

            if possible:
                sets[i].append(curr)
                if backtrack(curr + 1):
                    return True
                sets[i].pop()
        return False
    return backtrack(1)

for m in range(1, 4):
